23	}
24	
25	// WithDeleteUserFailpoint is a test-only helper that forces DeleteUser to roll back.
26	func WithDeleteUserFailpoint(ctx context.Context, failpoint DeleteUserFailpoint) context.Context {
27		return context.WithValue(ctx, deleteUserFailpointKey{}, failpoint)
28	}
29	
30	// GetDeleteUserFailpoint returns the delete-user failpoint attached to ctx, if any.
31	func GetDeleteUserFailpoint(ctx context.Context) DeleteUserFailpoint {
32		failpoint, ok := ctx.Value(deleteUserFailpointKey{}).(DeleteUserFailpoint)
33		if !ok {
34			return ""
35		}
36		return failpoint
37	}
